import {useEffect,useMemo,useState} from "react";

import useAppState from "./hooks/useAppState";

import {TITLES,TYPE_GROUPS,GENRES} from "./data/titles";

import {ageFromDate,applyTheme,hashPassword,listKey,uid} from "./lib";
import {getPopularMovies,searchMovies} from "./api/tmdb";



const TYPES={movies:"Movies",tv:"TV Shows",anime:"Anime",games:"Games",books:"Books",lightNovels:"Light Novels",manga:"Manga"};

const SLUG={movies:"movies",tv:"tv",anime:"anime",games:"games",books:"books",lightNovels:"light-novels",manga:"manga"};

const FROM_SLUG=Object.fromEntries(Object.entries(SLUG).map(([a,b])=>[b,a]));

const STATUSES=["Currently consuming","Plan to consume","Completed","On hold","Dropped","Favourites"];

const FORMATS=["Movies","Series","Anime","Games","Light novels","Books","Manga"];

const AVOID=["Gore","Graphic violence","Animal harm","Sexual violence","Spoilers","Jump scares"];

const IDENTITY=["Woman","Man","Non-binary","Genderqueer","Genderfluid","Agender","Trans woman","Trans man","Two-spirit","Questioning","Prefer to self-describe","Prefer not to say"];

const PRONOUNS=["she/her","he/him","they/them","other","ask me","Prefer not to say"];

const emptyProfile=()=>({displayName:"",bio:"",country:"",gender:"",pronouns:"",avatar:"",avatarColor:"#ff4fa3",private:false,genres:{},frequency:{},formats:FORMATS,avoid:[]});

const score=p=>(p.length>=10?1:0)+(/[a-z]/.test(p)?1:0)+(/[A-Z]/.test(p)?1:0)+(/[0-9]/.test(p)?1:0)+(/[^A-Za-z0-9]/.test(p)?1:0);

const initial=s=>(s||"FB").trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join("");

const pathNow=()=>location.pathname.replace(/\/+$/, "")||"/";

function Cover({t,onClick,className=""}){return <button className={`cover ${className} ${t.poster?"has-poster":""}`} style={{"--cover":t.cover||"#6f4965"}} onClick={onClick} aria-label={`Open ${t.title}`}>{t.poster&&<img className="poster-image" src={t.poster} alt="" loading="lazy" onError={e=>{e.currentTarget.style.display="none"}}/>}<span className="orbit"/><b className="symbol">{t.poster?"":t.symbol}</b><strong>{t.title}</strong><small>{t.typeLabel} · {t.year||"Year unknown"}</small></button>}

function Card({t,open,saved,add,rating}){return <article className="title-card"><Cover t={t} onClick={()=>open(t)}/><div className="card-copy"><div className="card-line"><button className="link title-name" onClick={()=>open(t)}>{t.title}</button><span className="rating">★ {(rating||t.rating).toFixed(1)}</span></div><p className="muted small">{t.typeLabel} · {t.year}</p><div className="chips">{t.genres.slice(0,2).map(g=><span key={g}>{g}</span>)}</div><button className={`btn ${saved?"ghost":"mini"}`} onClick={()=>add(t)}>{saved?"✓ In library":"+ Add to library"}</button></div></article>}

function Empty({title,body,action,onAction}){return <div className="empty"><span>✧</span><h3>{title}</h3><p>{body}</p>{action&&<button className="btn ghost" onClick={onAction}>{action}</button>}</div>}

function ThemeStudio({theme,change,close,toast}){const [hex,setHex]=useState(theme.accent||"#ff4fa3"),[hue,setHue]=useState(330),[sat,setSat]=useState(.8),[bright,setBright]=useState(1),[err,setErr]=useState("");

useEffect(()=>setHex(theme.accent||"#ff4fa3"),[theme.accent]);

const color=(h,s,v)=>{const f=n=>v-v*s*Math.max(Math.min((n+h/60)%6,4-(n+h/60)%6,1),0);return "#"+[f(5),f(3),f(1)].map(x=>Math.round(x*255).toString(16).padStart(2,"0")).join("")};

const apply=c=>{setHex(c);setErr("");change({...theme,mode:"dark",light:false,accent:c})};

const wheel=e=>{const r=e.currentTarget.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,h=(Math.atan2(y,x)*180/Math.PI+360)%360,s=Math.min(1,Math.hypot(x,y)/(r.width/2));setHue(h);setSat(s);apply(color(h,s,bright))};

const presets=[["Pink","#ff4fa3"],["Purple","#a78bfa"],["Red","#ff5d67"],["Blue","#5da9ff"],["Green","#64d98b"],["Orange","#ff9d54"],["Teal","#42d6c5"]];

return <div className="scrim" onMouseDown={e=>e.target===e.currentTarget&&close()}><aside className="theme-studio" role="dialog" aria-modal="true" aria-labelledby="theme-heading"><header className="row between"><div><p className="eyebrow">MAKE IT YOURS</p><h2 id="theme-heading">Theme studio</h2></div><button className="icon" onClick={close} aria-label="Close theme studio">×</button></header><div className="theme-preview"><b>fictionbook</b><strong>Your worlds, collected.</strong><span>Accent preview</span></div><h3>Accent presets</h3><div className="presets">{presets.map(([n,c])=><button key={n} className={`preset ${theme.accent===c&&theme.mode!=="rainbow"?"selected":""}`} onClick={()=>apply(c)}><i style={{background:c}}/>{n}</button>)}</div><button className={`rainbow-button ${theme.mode==="rainbow"?"selected":""}`} onClick={()=>{change({...theme,mode:"rainbow",light:false});toast("Rainbow Pride theme enabled")}}><i/> <span><b>Rainbow Pride</b><small>Rainbow gradients throughout the interface</small></span>✦</button><div className="wheel-grid"><div><h3>Colour wheel</h3><div className="colour-wheel" tabIndex="0" role="slider" aria-label="Hue and saturation colour wheel" onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);wheel(e)}} onPointerMove={e=>e.buttons===1&&wheel(e)} onKeyDown={e=>{if(e.key==="ArrowRight"){setHue(h=>h+5);apply(color(hue+5,sat,bright))}if(e.key==="ArrowLeft"){setHue(h=>h-5);apply(color(hue-5,sat,bright))}}}><span style={{background:color(hue,sat,bright)}}/></div><label className="label" htmlFor="brightness">Brightness · {Math.round(bright*100)}%</label><input id="brightness" type="range" min=".2" max="1" step=".01" value={bright} onChange={e=>{setBright(+e.target.value);apply(color(hue,sat,+e.target.value))}}/></div><div><h3>Custom HEX</h3><label className="label" htmlFor="hex">HEX colour</label><div className="hex-row"><i style={{background:/^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(hex)?hex:"#777"}}/><input id="hex" value={hex} maxLength="7" onChange={e=>{setHex(e.target.value);setErr("")}}/><button className="btn primary" onClick={()=>/^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(hex)?(apply(hex),toast("Theme applied")):setErr("Enter a valid HEX code, e.g. #FF4FA3.")}>Apply</button></div>{err&&<p className="error">{err}</p>}<button className="btn ghost wide" onClick={()=>{change({mode:"dark",accent:"#ff4fa3",light:false});setHex("#ff4fa3");toast("Reset to default pink")}}>Reset to pink</button><button className="btn ghost wide" onClick={()=>change({...theme,light:!theme.light,mode:theme.mode==="rainbow"?"dark":theme.mode})}>{theme.light?"Use dark base":"Optional light base"}</button></div></div><p className="muted small">Your theme is saved locally. Reduced-motion settings are respected.</p></aside></div>}

function TitleDetails({t,state,user,profile,rate,add,review,close,allReviews,open,allTitles}){const [stars,setStars]=useState(state.ratings[user?.id]?.[t.id]||0),[text,setText]=useState(""),[title,setTitle]=useState(""),[spoilers,setSpoilers]=useState(false),[revealed,setRevealed]=useState({});

const similar=allTitles.filter(x=>x.id!==t.id&&x.genres.some(g=>t.genres.includes(g))).slice(0,4);

return <div className="scrim" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="details" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button className="icon close" onClick={close} aria-label="Close">×</button><div className="detail-top"><Cover t={t} className="detail-cover" onClick={()=>{}}/><div><p className="eyebrow">{t.typeLabel} · {t.year}</p><h2 id="detail-title">{t.title}</h2><p className="muted">By {t.creator} · {t.length}</p><div className="chips">{t.genres.map(g=><span key={g}>{g}</span>)}</div><p>{t.description}</p><h3 className="rating-big">★ {t.rating.toFixed(1)} <small>sample community score</small></h3><label className="label">Your rating</label><div className="stars">{[1,2,3,4,5].map(n=><button key={n} className={n<=stars?"star on":"star"} aria-label={`${n} stars`} onClick={()=>{setStars(n);rate(t,n)}}>★</button>)}</div><div className="row wrap"><button className="btn primary" onClick={()=>add(t,"Currently consuming")}>Start now</button><button className="btn ghost" onClick={()=>add(t,"Plan to consume")}>Plan later</button><button className="btn ghost" onClick={()=>add(t,"Favourites")}>♡ Favourite</button><button className="btn ghost" onClick={()=>navigator.clipboard?.writeText(location.href)}>↗ Share</button></div></div></div><div className="review-form"><h3>Write a review</h3><label className="label">Review title (optional)</label><input value={title} maxLength="80" onChange={e=>setTitle(e.target.value)} placeholder="A few words about it"/><label className="label">Your review (20–2000 characters)</label><textarea value={text} maxLength="2000" rows="4" onChange={e=>setText(e.target.value)} placeholder="What did you think?"/><div className="row between wrap"><label className="check"><input type="checkbox" checked={spoilers} onChange={e=>setSpoilers(e.target.checked)}/> Contains spoilers</label><span className="muted small">{text.length}/2000</span><button disabled={text.trim().length<20} className="btn primary" onClick={()=>{review(t,{title,text:text.trim(),rating:stars,spoilers});setText("");setTitle("");setSpoilers(false)}}>Publish review</button></div></div><div className="review-list"><h3>Reviews ({allReviews.length})</h3>{allReviews.length?allReviews.map(r=><article className="review" key={r.id}><div className="row between"><b>{r.displayName}</b><span className="rating">★ {r.rating||"—"}</span></div>{r.title&&<h4>{r.title}</h4>}{r.spoilers&&!revealed[r.id]?<button className="spoiler" onClick={()=>setRevealed(v=>({...v,[r.id]:true}))}>Spoilers hidden — click to reveal</button>:<p>{r.text}</p>}</article>):<p className="muted small">No reviews yet. You could be the first.</p>}</div>{similar.length>0&&<div className="similar"><h3>More like this</h3>{similar.map(x=><button key={x.id} onClick={()=>open(x)}>{x.symbol} {x.title}</button>)}</div>}</section></div>}

export default function App(){

const [state,setState]=useAppState(),[tmdbMovies,setTmdbMovies]=useState([]),[tmdbLoading,setTmdbLoading]=useState(false),[tmdbError,setTmdbError]=useState(""),[tmdbSearchResults,setTmdbSearchResults]=useState([]),[path,setPath]=useState(pathNow()),[themeOpen,setThemeOpen]=useState(false),[toast,setToast]=useState(""),[detail,setDetail]=useState(null),[search,setSearch]=useState(""),[searchType,setSearchType]=useState("all"),[menu,setMenu]=useState(false),[profileMenu,setProfileMenu]=useState(false),[authError,setAuthError]=useState(""),[showPass,setShowPass]=useState(false),[recoveryEmail,setRecoveryEmail]=useState(""),[login,setLogin]=useState({id:"",password:"",remember:true}),[reg,setReg]=useState({username:"",email:"",password:"",confirm:"",displayName:"",dob:"",country:"",bio:"",gender:"",selfGender:"",pronouns:"",genres:{},frequency:{},formats:FORMATS,avoid:[],terms:false,privacy:false}),[step,setStep]=useState(0),[filters,setFilters]=useState({genres:[],sort:"popularity",page:1}),[libFilter,setLibFilter]=useState("all"),[libType,setLibType]=useState("all"),[libSort,setLibSort]=useState("newest"),[draft,setDraft]=useState(null),[postText,setPostText]=useState(""),[friendSearch,setFriendSearch]=useState(""),[tour,setTour]=useState(0),[showTour,setShowTour]=useState(false);

const allTitles=useMemo(()=>tmdbMovies.length?[...tmdbMovies,...TITLES.filter(t=>t.type!=="movies")]:TITLES,[tmdbMovies]);
useEffect(()=>{let alive=true;setTmdbLoading(true);getPopularMovies().then(m=>{if(alive){setTmdbMovies(m);setTmdbError("")}}).catch(e=>{if(alive)setTmdbError(e.message)}).finally(()=>{if(alive)setTmdbLoading(false)});return()=>{alive=false}},[]);
useEffect(()=>{let alive=true;if(search.trim()){searchMovies(search).then(m=>{if(alive)setTmdbSearchResults(m)}).catch(()=>{if(alive)setTmdbSearchResults([])})}else setTmdbSearchResults([]);return()=>{alive=false}},[search]);
const user=state.users.find(u=>u.id===state.currentUserId)||null,profile=user?{...emptyProfile(),...(state.profiles[user.id]||{})}:emptyProfile();

const notify=m=>{setToast(m);clearTimeout(window._fbToast);window._fbToast=setTimeout(()=>setToast(""),2800)};

const go=p=>{history.pushState({},"",p);setPath(pathNow());setMenu(false);setProfileMenu(false);setSearch("");window.scrollTo(0,0)};

useEffect(()=>{const fn=()=>setPath(pathNow());addEventListener("popstate",fn);return()=>removeEventListener("popstate",fn)},[]);

useEffect(()=>applyTheme(state.theme||{mode:"dark",accent:"#ff4fa3"}),[state.theme]);

useEffect(()=>{if(user&&!state.onboardingDone[user.id]&&path==="/")setShowTour(true)},[user?.id]);

const open=t=>{setDetail(t);if(user)setState(s=>({...s,recentlyViewed:[{userId:user.id,titleId:t.id,date:new Date().toISOString()},...(s.recentlyViewed||[]).filter(x=>x.userId!==user.id||x.titleId!==t.id)].slice(0,80)}));history.replaceState({},"",`/title/${t.id}`);setPath(`/title/${t.id}`)};

useEffect(()=>{const m=path.match(/^\/title\/([^/]+)/);if(m){const t=allTitles.find(x=>x.id===m[1]);if(t)setDetail(t)}else if(!path.startsWith("/title/"))setDetail(null)},[path,allTitles]);

const saved=t=>!!(user&&state.lists[listKey(user.id,t.id)]), rating=t=>state.ratings[user?.id]?.[t.id]||0;

const add=(t,status="Plan to consume")=>{if(!user){notify("Log in to save titles.");go("/login");return}setState(s=>({...s,lists:{...s.lists,[listKey(user.id,t.id)]:{status,progress:s.lists[listKey(user.id,t.id)]?.progress||0,addedAt:s.lists[listKey(user.id,t.id)]?.addedAt||new Date().toISOString()}}}));notify(`Added to ${status.toLowerCase()}.`)};

const remove=t=>setState(s=>{const lists={...s.lists};delete lists[listKey(user.id,t.id)];return {...s,lists}});

const rate=(t,n)=>{if(!user){notify("Log in to rate titles.");return}setState(s=>({...s,ratings:{...s.ratings,[user.id]:{...(s.ratings[user.id]||{}),[t.id]:n}}}));notify("Rating saved.")};

const reviewsFor=t=>state.users.flatMap(u=>(state.reviews[u.id]||[]).filter(r=>r.titleId===t.id));

const review=(t,r)=>{if(!user){notify("Log in to review titles.");return}setState(s=>({...s,reviews:{...s.reviews,[user.id]:[{...r,id:uid(),titleId:t.id,userId:user.id,displayName:profile.displayName||user.username,date:new Date().toISOString()},...(s.reviews[user.id]||[])]}}));notify("Review saved.")};

const items=useMemo(()=>user?allTitles.map(t=>({...t,entry:state.lists[listKey(user.id,t.id)]})).filter(t=>t.entry):[],[user?.id,state.lists]);

const recommendations=useMemo(()=>{const prefs=Object.values(profile.genres||{}).flat();return allTitles.filter(t=>!profile.avoid?.some(a=>a!=="Spoilers"&&t.description.toLowerCase().includes(a.toLowerCase()))).map(t=>({...t,_s:t.genres.filter(g=>prefs.includes(g)).length*3+(rating(t)>=4?2:0)+(saved(t)?-2:1)})).sort((a,b)=>b._s-a._s)},[user?.id,state.lists,state.ratings,profile.genres,profile.avoid]);

const results=useMemo(()=>{if(!search)return [];const local=allTitles.filter(t=>(searchType==="all"||t.type===searchType)&&`${t.title} ${t.description} ${t.creator} ${t.genres.join(" ")}`.toLowerCase().includes(search.toLowerCase()));return [...tmdbSearchResults.filter(t=>searchType==="all"||searchType==="movies"),...local.filter(t=>!tmdbSearchResults.some(m=>m.id===t.id))].slice(0,8)},[search,searchType,tmdbSearchResults,allTitles]);

const categoryPath=path.match(/^\/browse\/([^/]+)/),browseType=categoryPath?FROM_SLUG[categoryPath[1]]:"";

const browse=useMemo(()=>{let arr=allTitles.filter(t=>t.type===browseType);if(filters.genres.length)arr=arr.filter(t=>filters.genres.every(g=>t.genres.includes(g)));if(filters.sort==="rating")arr.sort((a,b)=>b.rating-a.rating);if(filters.sort==="newest")arr.sort((a,b)=>b.year-a.year);if(filters.sort==="az")arr.sort((a,b)=>a.title.localeCompare(b.title));if(filters.sort==="popularity")arr.sort((a,b)=>b.popularity-a.popularity);return arr},[browseType,filters]);

const lib=useMemo(()=>items.filter(t=>(libFilter==="all"||t.entry.status===libFilter)&&(libType==="all"||t.type===libType)).sort((a,b)=>libSort==="az"?a.title.localeCompare(b.title):new Date(b.entry.addedAt)-new Date(a.entry.addedAt)),[items,libFilter,libType,libSort]);

const openProfileEdit=()=>{setDraft(profile);go("/profile/edit")};

const signOut=()=>{setState(s=>({...s,currentUserId:null}));go("/login");notify("Logged out.")};

const loginSubmit=async e=>{e.preventDefault();setAuthError("");const u=state.users.find(x=>x.username.toLowerCase()===login.id.toLowerCase()||x.email.toLowerCase()===login.id.toLowerCase());if(!u){setAuthError("No account found for that username or email.");return}try{const h=await hashPassword(login.password,u.salt);if(h.hash!==u.passwordHash){setAuthError("That password doesn't match this account.");return}}catch(err){setAuthError(err.message);return}setState(s=>({...s,currentUserId:u.id,rememberMe:login.remember}));go("/");notify(`Welcome back, ${u.displayName||u.username}!`)};

const registerSubmit=async()=>{setAuthError("");if(step===0&&(!reg.username.trim()||reg.username.length<3||!reg.email.includes("@")||score(reg.password)<4||reg.password.length<10||reg.confirm!==reg.password)){setAuthError("Use a unique username, valid email, strong password (10+ chars, mixed types), and matching confirmation.");return}if(step===1&&(!reg.displayName.trim()||ageFromDate(reg.dob)<13)){setAuthError("Enter a display name and valid birth date. You must be at least 13.");return}if(step<4){setStep(step+1);return}if(!reg.terms||!reg.privacy){setAuthError("Accept the terms and privacy notice to continue.");return}if(state.users.some(u=>u.username.toLowerCase()===reg.username.toLowerCase())){setAuthError("That username is already taken.");setStep(0);return}if(state.users.some(u=>u.email.toLowerCase()===reg.email.toLowerCase())){setAuthError("That email is already registered.");setStep(0);return}try{const h=await hashPassword(reg.password),u={id:uid(),username:reg.username.trim(),email:reg.email.trim().toLowerCase(),passwordHash:h.hash,salt:h.salt,displayName:reg.displayName,createdAt:new Date().toISOString()},p={...emptyProfile(),displayName:reg.displayName,bio:reg.bio,country:reg.country,gender:reg.gender==="Prefer to self-describe"?reg.selfGender:reg.gender,pronouns:reg.pronouns,genres:reg.genres,frequency:reg.frequency,formats:reg.formats,avoid:reg.avoid};setState(s=>({...s,users:[...s.users,u],currentUserId:u.id,profiles:{...s.profiles,[u.id]:p},onboardingDone:{...s.onboardingDone,[u.id]:false}}));setStep(0);go("/");notify("Welcome to FictionBook!")}catch(e){setAuthError(e.message)}};

const sendFriend=target=>{if(!user){go("/login");return}if(target.id===user.id)return notify("That's you!");if((state.friends[user.id]||[]).includes(target.id))return notify("Already friends.");setState(s=>({...s,friendRequests:{...s.friendRequests,[target.id]:[...new Set([...(s.friendRequests[target.id]||[]),user.id])]}}));notify("Friend request sent in this local demo.")};

const doShare=async p=>{try{await navigator.clipboard.writeText(location.origin+p);notify("Link copied.")}catch{notify("Copy the URL from your address bar.")}};

const cards=(arr)=>arr.length?<div className="grid">{arr.map(t=><Card key={t.id} t={t} open={open} saved={saved(t)} add={x=>saved(x)?remove(x):add(x)} rating={t.rating}/>)}</div>:<Empty title="Nothing on this shelf yet" body="Try another filter or add a title to your library." action="Browse titles" onAction={()=>go("/browse/movies")}/>;

const navTypes=Object.entries(TYPES);

const Header=()=> <header className="topbar"><button className="brand" onClick={()=>go("/") }><i>f.</i>fiction<span>book</span></button><div className="searchbox"><span>⌕</span><input aria-label="Search all titles" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search your next obsession…"/>{search&&<div className="search-pop"><div className="row between"><select value={searchType} onChange={e=>setSearchType(e.target.value)}><option value="all">All categories</option>{navTypes.map(([v,n])=><option key={v} value={v}>{n}</option>)}</select><button className="link" onClick={()=>go(`/search?q=${encodeURIComponent(search)}`)}>See all →</button></div>{results.length?results.map(t=><button key={t.id} className="search-hit" onClick={()=>{open(t);setSearch("")}}><i style={{background:t.cover}}>{t.symbol}</i><span><b>{t.title}</b><small>{t.typeLabel} · {t.year}</small></span></button>):<p className="muted small">No matches found.</p>}</div>}</div><nav className={menu?"nav open":"nav"}><button onClick={()=>go("/category/watchable")}>Watchable</button><button onClick={()=>go("/category/playable")}>Playable</button><button onClick={()=>go("/category/readable")}>Readable</button><button onClick={()=>user?go("/library"):go("/login")}>My Library</button><button className="theme-nav" onClick={()=>setThemeOpen(true)}>◐ Theme</button></nav><div className="user-nav">{user?<><button className="avatar" style={{background:profile.avatarColor}} onClick={()=>setProfileMenu(!profileMenu)} aria-label="Profile menu">{profile.avatar?<img src={profile.avatar} alt=""/>:initial(profile.displayName||user.username)}</button>{profileMenu&&<div className="dropdown"><b>{profile.displayName||user.username}</b><small>@{user.username}</small><button onClick={()=>go(`/profile/${user.username}`)}>View profile</button><button onClick={openProfileEdit}>Edit profile</button><button onClick={()=>go("/settings")}>Settings</button><button onClick={signOut}>Log out</button></div>}</>:<><button className="btn ghost" onClick={()=>go("/login")}>Log in</button><button className="btn primary" onClick={()=>go("/register")}>Join</button></>}<button className="hamburger" onClick={()=>setMenu(!menu)} aria-label="Toggle navigation">☰</button></div></header>;

const Auth=()=>{const loginPage=path==="/login";const recovery=path==="/forgot-password";return <main className="auth"><section className="auth-art"><p className="eyebrow">A HOME FOR EVERY STORY</p><h1>Your worlds,<br/><em>collected.</em></h1><p>Track what moves you. Find your next favourite. Make the library yours.</p><div className="auth-stats"><b>7<small> media types</small></b><b>∞<small> stories to explore</small></b></div></section><section className="auth-card">{loginPage?<><p className="eyebrow">WELCOME BACK</p><h2>Pick up where you left off.</h2><p className="muted">Your library is waiting.</p><form onSubmit={loginSubmit}><label className="label">Username or email</label><input required autoComplete="username" value={login.id} onChange={e=>setLogin({...login,id:e.target.value})} placeholder="you@example.com"/><label className="label">Password</label><div className="password"><input required type={showPass?"text":"password"} autoComplete="current-password" value={login.password} onChange={e=>setLogin({...login,password:e.target.value})}/><button type="button" className="link" onClick={()=>setShowPass(!showPass)}>{showPass?"Hide":"Show"}</button></div><label className="check"><input type="checkbox" checked={login.remember} onChange={e=>setLogin({...login,remember:e.target.checked})}/> Remember me</label>{authError&&<p className="error">{authError}</p>}<button className="btn primary wide">Log in →</button></form><p className="muted small center">Forgot password? <button className="link" onClick={()=>go("/forgot-password")}>Try demo recovery</button></p><p className="muted small center">New here? <button className="link" onClick={()=>go("/register")}>Create an account</button></p></>:recovery?<><p className="eyebrow">ACCOUNT RECOVERY</p><h2>Reset your password.</h2><p className="muted">Demo mode: no email is sent and password recovery is not connected to a server.</p><form onSubmit={e=>{e.preventDefault();const found=state.users.some(u=>u.email===recoveryEmail.toLowerCase());setAuthError(found?"This demo cannot email a reset link. Log in with your current password or create a new local account.":"No account was found for that email.");}}><label className="label">Email address</label><input type="email" required value={recoveryEmail} onChange={e=>setRecoveryEmail(e.target.value)}/>{authError&&<p className="error">{authError}</p>}<button className="btn primary wide">Check account</button></form><p className="muted small center"><button className="link" onClick={()=>go("/login")}>Back to login</button></p></>:<><p className="eyebrow">MAKE YOURSELF AT HOME</p><h2>Create your account.</h2><p className="muted">Step {step+1} of 5 · {["Account","About you","Identity","Taste profile","Review"][step]}</p><div className="steps">{[0,1,2,3,4].map(n=><i key={n} className={n<=step?"done":""}/>)}</div><div className="register">

{step===0&&<><label className="label">Username *</label><input required minLength="3" value={reg.username} onChange={e=>setReg({...reg,username:e.target.value.replace(/\s/g,"")})} placeholder="3+ characters"/><label className="label">Email *</label><input required type="email" value={reg.email} onChange={e=>setReg({...reg,email:e.target.value})} placeholder="you@example.com"/><label className="label">Password *</label><div className="password"><input required type={showPass?"text":"password"} value={reg.password} onChange={e=>setReg({...reg,password:e.target.value})}/><button className="link" onClick={()=>setShowPass(!showPass)}>{showPass?"Hide":"Show"}</button></div><div className="strength"><i style={{width:`${score(reg.password)*20}%`}}/></div><p className="muted small">10+ characters with uppercase, lowercase, a number and a symbol.</p><label className="label">Confirm password *</label><input required type="password" value={reg.confirm} onChange={e=>setReg({...reg,confirm:e.target.value})}/></>}

{step===1&&<><label className="label">Display name *</label><input value={reg.displayName} onChange={e=>setReg({...reg,displayName:e.target.value})} required/><label className="label">Date of birth * (13+)</label><input type="date" value={reg.dob} max={new Date(new Date().setFullYear(new Date().getFullYear()-13)).toISOString().slice(0,10)} onChange={e=>setReg({...reg,dob:e.target.value})} required/><label className="label">Country (optional)</label><input value={reg.country} onChange={e=>setReg({...reg,country:e.target.value})}/><label className="label">Short bio (optional)</label><textarea rows="3" maxLength="240" value={reg.bio} onChange={e=>setReg({...reg,bio:e.target.value})}/></>}

{step===2&&<><p className="muted small">Every identity question is optional. You can skip these or change them later.</p><label className="label">Gender</label><select value={reg.gender} onChange={e=>setReg({...reg,gender:e.target.value})}><option value="">Choose if you wish</option>{IDENTITY.map(x=><option key={x}>{x}</option>)}</select>{reg.gender==="Prefer to self-describe"&&<input placeholder="Describe your gender" value={reg.selfGender} onChange={e=>setReg({...reg,selfGender:e.target.value})}/>}<label className="label">Pronouns</label><select value={reg.pronouns} onChange={e=>setReg({...reg,pronouns:e.target.value})}><option value="">Choose if you wish</option>{PRONOUNS.map(x=><option key={x}>{x}</option>)}</select></>}

{step===3&&<><p className="muted small">Choose genres by category to tune your recommendations.</p>{["Watchable","Playable","Readable"].map(c=><div className="taste" key={c}><b>{c}</b><div className="choices">{GENRES.map(g=><label className={`choice ${(reg.genres[c]||[]).includes(g)?"chosen":""}`} key={g}><input type="checkbox" checked={(reg.genres[c]||[]).includes(g)} onChange={e=>setReg({...reg,genres:{...reg.genres,[c]:e.target.checked?[...(reg.genres[c]||[]),g]:(reg.genres[c]||[]).filter(x=>x!==g)}})}/>{g}</label>)}</div></div>)}<label className="label">How often do you…</label>{["Watch","Play","Read"].map(c=><div className="frequency" key={c}><span>{c}</span><select value={reg.frequency[c]||""} onChange={e=>setReg({...reg,frequency:{...reg.frequency,[c]:e.target.value}})}><option value="">Choose</option>{["Daily","Several times a week","Weekly","Monthly","Occasionally"].map(x=><option key={x}>{x}</option>)}</select></div>)}<label className="label">Preferred formats</label><div className="choices">{FORMATS.map(f=><label className={`choice ${reg.formats.includes(f)?"chosen":""}`} key={f}><input type="checkbox" checked={reg.formats.includes(f)} onChange={e=>setReg({...reg,formats:e.target.checked?[...reg.formats,f]:reg.formats.filter(x=>x!==f)})}/>{f}</label>)}</div><label className="label">Content to avoid</label><div className="choices">{AVOID.map(f=><label className={`choice ${reg.avoid.includes(f)?"chosen":""}`} key={f}><input type="checkbox" checked={reg.avoid.includes(f)} onChange={e=>setReg({...reg,avoid:e.target.checked?[...reg.avoid,f]:reg.avoid.filter(x=>x!==f)})}/>{f}</label>)}</div></>}

{step===4&&<><div className="summary"><b>@{reg.username}</b><span>{reg.email}</span><span>{reg.displayName} · {reg.dob}</span><span>{reg.gender||"Identity not shared"} · {reg.pronouns||"Pronouns not shared"}</span><span>{Object.values(reg.genres).flat().length} genre preferences · {reg.formats.length} formats</span></div><label className="check"><input type="checkbox" checked={reg.terms} onChange={e=>setReg({...reg,terms:e.target.checked})}/> I accept the Terms of Service *</label><label className="check"><input type="checkbox" checked={reg.privacy} onChange={e=>setReg({...reg,privacy:e.target.checked})}/> I have read the Privacy Notice *</label><p className="demo-note">Demo authentication only. Passwords are hashed before local storage, but localStorage is not production security. Do not use a real password.</p></>}

{authError&&<p className="error" role="alert">{authError}</p>}<div className="row between"><button className="btn ghost" disabled={step===0} onClick={()=>{setStep(step-1);setAuthError("")}}>← Back</button><button className="btn primary" onClick={registerSubmit}>{step===4?"Create account":"Continue →"}</button></div></div><p className="muted small center">Already registered? <button className="link" onClick={()=>go("/login")}>Log in</button></p></>}</section></main>};

let content;

if(["/login","/register","/forgot-password"].includes(path))content=Auth();

else if(path==="/")content=<main><section className="hero"><div><p className="eyebrow">YOUR PERSONAL MEDIA UNIVERSE</p><h1>Every story leaves<br/>a <em>little something.</em></h1><p>One home for what you watch, play and read. Keep track of what you love—and what comes next.</p><div className="row wrap"><button className="btn primary" onClick={()=>go("/category/watchable")}>Explore the library ↗</button><button className="btn ghost" onClick={()=>user?go("/library"):go("/login")}>My collection</button></div><p className="eyebrow hero-foot">✦ YOUR TASTE, YOUR SPACE · 7 MEDIA TYPES</p></div><div className="hero-art">{allTitles.filter((_,i)=>i%7===0).slice(0,5).map((t,i)=><button className={`float float-${i}`} key={t.id} style={{"--cover":t.cover}} onClick={()=>open(t)}><span>{t.symbol}</span><b>{t.title}</b></button>)}</div></section><div className="container">

{user&&items.some(t=>t.entry.status==="Currently consuming")&&<section className="section"><Heading eyebrow="PICK UP WHERE YOU LEFT OFF" title="Continue your journey" action="View library" click={()=>go("/library")}/><div className="continue-list">{items.filter(t=>t.entry.status==="Currently consuming").slice(0,4).map(t=><div className="continue" key={t.id}><Cover t={t} onClick={()=>open(t)}/><div><b>{t.title}</b><p className="muted small">{t.entry.progress||0}% complete</p><input type="range" min="0" max="100" value={t.entry.progress||0} onChange={e=>setState(s=>({...s,lists:{...s.lists,[listKey(user.id,t.id)]:{...s.lists[listKey(user.id,t.id)],progress:+e.target.value}}}))}/></div></div>)}</div></section>}

<section className="section"><Heading eyebrow={user?"TUNED TO YOUR TASTE":"A FEW PLACES TO START"} title="Recommended for you" action="Explore all" click={()=>go("/category/watchable")}/>{cards(recommendations.slice(0,6))}</section>

<section className="section category-tiles">{Object.entries(TYPE_GROUPS).map(([cat,types])=><button key={cat} onClick={()=>go(`/category/${cat.toLowerCase()}`)}><i>{cat==="Watchable"?"◉":cat==="Playable"?"⌘":"▤"}</i><span><b>{cat}</b><small>{types.reduce((n,t)=>n+allTitles.filter(x=>x.type===t).length,0)} titles to explore</small></span><strong>↗</strong></button>)}</section>

{Object.entries(TYPE_GROUPS).map(([cat,types])=><section className="section" key={cat}><Heading eyebrow={cat==="Watchable"?"ON THE SCREEN":cat==="Playable"?"IN YOUR HANDS":"BETWEEN THE COVERS"} title={cat} action="Browse all" click={()=>go(`/category/${cat.toLowerCase()}`)}/><div className="featured">{allTitles.filter(t=>types.includes(t.type)).slice(0,5).map(t=><button key={t.id} onClick={()=>open(t)}><Cover t={t} onClick={()=>open(t)}/><b>{t.title}</b><small>★ {t.rating.toFixed(1)} · {t.year}</small></button>)}</div></section>)}

<section className="surprise"><div><p className="eyebrow">FEELING INDECISIVE?</p><h2>Let the library decide.</h2><p className="muted">A random doorway to your next favourite thing.</p></div><button className="btn primary" onClick={()=>open(allTitles[Math.floor(Math.random()*allTitles.length)])}>✧ Surprise me</button></section>

<section className="section"><Heading title="Recently viewed"/>{user&&state.recentlyViewed.filter(x=>x.userId===user.id).length?cards(state.recentlyViewed.filter(x=>x.userId===user.id).slice(0,4).map(x=>allTitles.find(t=>t.id===x.titleId)).filter(Boolean)): <Empty title="Your story starts here" body="Open a title and it will appear here." action="Browse titles" onAction={()=>go("/category/watchable")}/>}</section></div></main>;

else if(path.startsWith("/category/")){const cat=path.split("/")[2],name=cat==="watchable"?"Watchable":cat==="playable"?"Playable":"Readable",types=TYPE_GROUPS[name];content=<main className="container page"><Heading eyebrow="EXPLORE BY FORMAT" title={name}/><div className="type-nav">{types.map(t=><button key={t} onClick={()=>go(`/browse/${SLUG[t]}`)}>{TYPES[t]} ↗</button>)}</div>{cards(allTitles.filter(t=>types.includes(t.type)))}</main>}

else if(path.startsWith("/browse/")){const type=browseType;content=<main className="container page"><Heading eyebrow="FIND YOUR NEXT FAVOURITE" title={TYPES[type]||"Browse"}/><div className="type-nav">{navTypes.map(([k,n])=><button className={type===k?"active":""} key={k} onClick={()=>go(`/browse/${SLUG[k]}`)}>{n}</button>)}</div><div className="browse-layout"><aside className="filters"><div className="row between"><b>Filters</b><button className="link" onClick={()=>setFilters({genres:[],sort:"popularity",page:1})}>Clear all</button></div><label className="label">Sort by</label><select value={filters.sort} onChange={e=>setFilters({...filters,sort:e.target.value,page:1})}><option value="popularity">Popularity</option><option value="rating">Rating</option><option value="newest">Newest</option><option value="az">A–Z</option></select><label className="label">Genres</label>{[...new Set(allTitles.filter(t=>t.type===type).flatMap(t=>t.genres))].sort().map(g=><label className="filter-check" key={g}><input type="checkbox" checked={filters.genres.includes(g)} onChange={e=>setFilters({...filters,genres:e.target.checked?[...filters.genres,g]:filters.genres.filter(x=>x!==g),page:1})}/>{g}</label>)}<p className="muted small">{browse.length} results</p></aside><div>{browse.length?cards(browse.slice((filters.page-1)*8,filters.page*8)):<Empty title="No titles match those filters" body="Try removing a genre or clearing your filters." action="Clear filters" onAction={()=>setFilters({genres:[],sort:"popularity",page:1})}/>}{browse.length>8&&<div className="pagination"><button className="btn ghost" disabled={filters.page===1} onClick={()=>setFilters({...filters,page:filters.page-1})}>← Previous</button><span>Page {filters.page} / {Math.ceil(browse.length/8)}</span><button className="btn ghost" disabled={filters.page>=Math.ceil(browse.length/8)} onClick={()=>setFilters({...filters,page:filters.page+1})}>Next →</button></div>}</div></div></main>}

else if(path==="/search"||path.startsWith("/search?")){const q=new URLSearchParams(location.search).get("q")||"";content=<main className="container page"><Heading title={`Results for “${q}”`}/>{cards(allTitles.filter(t=>`${t.title} ${t.description} ${t.genres.join(" ")}`.toLowerCase().includes(q.toLowerCase())))}</main>}

else if(path==="/library"){if(!user)content=<main className="container page"><Empty title="Your library is yours" body="Log in to collect titles." action="Log in" onAction={()=>go("/login")}/></main>;else {const completed=items.filter(t=>t.entry.status==="Completed").length,avg=Object.values(state.ratings[user.id]||{});content=<main className="container page"><Heading eyebrow="YOUR PERSONAL ARCHIVE" title="My Library." action="+ Add titles" click={()=>go("/category/watchable")}/><div className="stats"><div><b>{items.length}</b><small>Collected</small></div><div><b>{completed}</b><small>Completed</small></div><div><b>{avg.length?(avg.reduce((a,b)=>a+b,0)/avg.length).toFixed(1):"—"}</b><small>Average rating</small></div><div><b>{[...new Set(items.flatMap(t=>t.genres))].slice(0,2).join(" · ")||"—"}</b><small>Favourite genres</small></div></div><div className="library-toolbar"><div className="status-tabs">{["all",...STATUSES].map(s=><button key={s} className={libFilter===s?"active":""} onClick={()=>setLibFilter(s)}>{s==="all"?"All titles":s}</button>)}</div><select value={libType} onChange={e=>setLibType(e.target.value)}><option value="all">All types</option>{navTypes.map(([v,n])=><option key={v} value={v}>{n}</option>)}</select><select value={libSort} onChange={e=>setLibSort(e.target.value)}><option value="newest">Recently added</option><option value="az">A–Z</option></select></div>{lib.length?<div className="library-list">{lib.map(t=><article className="library-row" key={t.id}><Cover t={t} onClick={()=>open(t)}/><div><button className="link" onClick={()=>open(t)}>{t.title}</button><p className="muted small">{t.typeLabel} · {t.year}</p><div className="chips">{t.genres.map(g=><span key={g}>{g}</span>)}</div></div><div><label className="label">{t.entry.status}</label>{t.entry.status==="Currently consuming"?<><input type="range" min="0" max="100" value={t.entry.progress||0} onChange={e=>setState(s=>({...s,lists:{...s.lists,[listKey(user.id,t.id)]:{...s.lists[listKey(user.id,t.id)],progress:+e.target.value}}}))}/><small className="muted">{t.entry.progress||0}%</small></>:<select value={t.entry.status} onChange={e=>add(t,e.target.value)}>{STATUSES.map(s=><option key={s}>{s}</option>)}</select>}</div><button className="icon" aria-label={`Remove ${t.title}`} onClick={()=>{if(confirm(`Remove "${t.title}" from your library?`)){remove(t);notify("Removed from library.")}}}>×</button></article>)}</div>:<Empty title="A shelf waiting for stories" body="Add titles to build your personal library." action="Discover titles" onAction={()=>go("/category/watchable")}/>}</main>}}

else if(path.startsWith("/profile/edit"))content=<main className="container page narrow"><Heading title="Edit profile"/>{draft&&<div className="settings"><label className="label">Display name</label><input value={draft.displayName} onChange={e=>setDraft({...draft,displayName:e.target.value})}/><label className="label">Bio</label><textarea rows="4" value={draft.bio} onChange={e=>setDraft({...draft,bio:e.target.value})}/><label className="label">Pronouns</label><select value={draft.pronouns} onChange={e=>setDraft({...draft,pronouns:e.target.value})}><option value="">Not specified</option>{PRONOUNS.map(p=><option key={p}>{p}</option>)}</select><label className="label">Gender</label><input value={draft.gender} onChange={e=>setDraft({...draft,gender:e.target.value})}/><label className="label">Avatar image (under 1 MB)</label><input type="file" accept="image/*" onChange={e=>{const f=e.target.files?.[0];if(f&&f.size>1024*1024){notify("Choose an image under 1 MB.");return}if(f){const r=new FileReader();r.onload=()=>setDraft({...draft,avatar:r.result});r.readAsDataURL(f)}}}/><label className="label">Avatar colour</label><input type="color" value={draft.avatarColor} onChange={e=>setDraft({...draft,avatarColor:e.target.value})}/><div className="row end"><button className="btn ghost" onClick={()=>go(`/profile/${user.username}`)}>Cancel</button><button className="btn primary" onClick={()=>{setState(s=>({...s,profiles:{...s.profiles,[user.id]:draft}}));go(`/profile/${user.username}`);notify("Profile saved.")}}>Save profile</button></div></div>}</main>

else if(path.startsWith("/profile/")||path==="/profile"){const name=path.split("/")[2]||user?.username,target=state.users.find(u=>u.username.toLowerCase()===String(name).toLowerCase())||user;if(!target)content=<main className="container page"><Empty title="Profile not found" body="This profile is not in this browser." action="Go home" onAction={()=>go("/")}/></main>;else{const p={...emptyProfile(),...(state.profiles[target.id]||{})},own=target.id===user?.id,entries=allTitles.map(t=>({...t,entry:state.lists[listKey(target.id,t.id)]})).filter(t=>t.entry),reviews=state.reviews[target.id]||[],ratings=Object.entries(state.ratings[target.id]||{}).map(([id,r])=>({t:allTitles.find(t=>t.id===id),r})).filter(x=>x.t),posts=state.posts.filter(x=>x.userId===target.id);content=p.private&&!own?<main className="container page"><Empty title="This profile is private" body="This member has chosen to keep their profile private."/></main>:<main className="container page profile-page"><div className="profile-cover"/><div className="profile-id"><div className="avatar big" style={{background:p.avatarColor}}>{p.avatar?<img src={p.avatar} alt=""/>:initial(p.displayName||target.username)}</div><div className="profile-name"><h1>{p.displayName||target.username}</h1><span className="muted">@{target.username} {p.pronouns&&"· "+p.pronouns}</span><p>{p.bio||"Collecting stories, one world at a time."}</p><small className="muted">Member since {new Date(target.createdAt).toLocaleDateString(undefined,{month:"long",year:"numeric"})}</small></div><div className="row wrap">{own?<button className="btn primary" onClick={()=>{setDraft(p);go("/profile/edit")}}>Edit profile</button>:<button className="btn primary" onClick={()=>sendFriend(target)}>＋ Add friend</button>}<button className="btn ghost" onClick={()=>doShare(`/profile/${target.username}`)}>↗ Share</button></div></div><div className="stats five"><div><b>{entries.length}</b><small>Library items</small></div><div><b>{entries.filter(t=>t.entry.status==="Completed").length}</b><small>Completed</small></div><div><b>{ratings.length}</b><small>Ratings</small></div><div><b>{reviews.length}</b><small>Reviews</small></div><div><b>{posts.length}</b><small>Posts</small></div></div><div className="profile-columns"><div><section className="section"><Heading title="Recently added" action={own?"View library":undefined} click={()=>go("/library")}/>{cards(entries.slice().sort((a,b)=>new Date(b.entry.addedAt)-new Date(a.entry.addedAt)).slice(0,4))}</section><section className="section"><Heading title="Recent reviews"/>{reviews.length?reviews.slice(0,5).map(r=><article className="review" key={r.id}><b>{allTitles.find(t=>t.id===r.titleId)?.title}</b><span className="rating"> ★ {r.rating||"—"}</span><h4>{r.title}</h4><p>{r.spoilers?"Spoiler review — hidden in profile preview":r.text}</p><small className="muted">{new Date(r.date).toLocaleDateString()}</small>{own&&<button className="link" onClick={()=>{if(confirm("Delete this review?")){setState(s=>({...s,reviews:{...s.reviews,[user.id]:s.reviews[user.id].filter(x=>x.id!==r.id)}}));notify("Review deleted.")}}}>Delete review</button>}</article>):<p className="muted small">No reviews yet.</p>}</section><section className="section"><Heading title="Recent posts"/>{posts.length?posts.slice(0,4).map(pst=><article className="review" key={pst.id}><small className="muted">{new Date(pst.date).toLocaleString()}</small><p>{pst.text}</p></article>):<p className="muted small">No posts yet.</p>}</section></div><aside><section className="sidebox"><h3>About</h3><p>{p.country||"Location not shared"}</p><p>{p.gender||"Identity not shared"}</p><h4>Favourite genres</h4><div className="chips">{[...new Set(entries.flatMap(t=>t.genres))].slice(0,6).map(g=><span key={g}>{g}</span>)}</div></section><section className="sidebox"><h3>Favourite titles</h3>{entries.filter(t=>t.entry.status==="Favourites").map(t=><p key={t.id}><button className="link" onClick={()=>open(t)}>{t.title}</button></p>)}</section><section className="sidebox"><h3>Ratings</h3>{ratings.slice(0,6).map(x=><p key={x.t.id} className="row between small"><span>{x.t.title}</span><b className="rating">★ {x.r}</b></p>)}</section></aside></div></main>}}

else if(path==="/settings")content=<main className="container page narrow"><Heading title="Settings"/><div className="settings"><h3>Privacy</h3><label className="check"><input type="checkbox" checked={profile.private} onChange={e=>setState(s=>({...s,profiles:{...s.profiles,[user.id]:{...profile,private:e.target.checked}}}))}/> Make my profile private</label><hr/><h3>Your data</h3><button className="btn ghost wide" onClick={()=>{const data={user:{...user,passwordHash:undefined,salt:undefined},profile,lists:Object.fromEntries(Object.entries(state.lists).filter(([k])=>k.startsWith(user.id+":"))),ratings:state.ratings[user.id],reviews:state.reviews[user.id],posts:state.posts.filter(p=>p.userId===user.id),theme:state.theme};const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}));a.download="fictionbook-data.json";a.click();URL.revokeObjectURL(a.href);notify("Data export ready.")}}>Export my data as JSON</button><button className="btn ghost wide" onClick={()=>{if(confirm("Clear this account's library, ratings, reviews and posts?"))setState(s=>({...s,lists:Object.fromEntries(Object.entries(s.lists).filter(([k])=>!k.startsWith(user.id+":"))),ratings:{...s.ratings,[user.id]:{}},reviews:{...s.reviews,[user.id]:[]},posts:s.posts.filter(p=>p.userId!==user.id)}))}}>Clear activity data</button><button className="btn danger wide" onClick={()=>{if(confirm("Delete your account and its data? This cannot be undone.")){setState(s=>({...s,users:s.users.filter(u=>u.id!==user.id),currentUserId:null,profiles:Object.fromEntries(Object.entries(s.profiles).filter(([k])=>k!==user.id)),ratings:Object.fromEntries(Object.entries(s.ratings).filter(([k])=>k!==user.id)),reviews:Object.fromEntries(Object.entries(s.reviews).filter(([k])=>k!==user.id))}));go("/register")}}}>Delete account</button><p className="muted small">Demo authentication only. Data and hashes are stored in this browser; use a backend for production.</p></div></main>

else if(path==="/community"){if(!user)content=<main className="container page"><Empty title="Join the conversation" body="Log in to post and manage friend requests." action="Log in" onAction={()=>go("/login")}/></main>;else{const friends=state.friends[user.id]||[],incoming=state.friendRequests[user.id]||[],others=state.users.filter(u=>u.id!==user.id&&!friends.includes(u.id));content=<main className="container page"><Heading eyebrow="THE COMMON ROOM" title="Community."/><div className="community-columns"><div><div className="settings"><b>{profile.displayName||user.username}</b><textarea rows="3" maxLength="600" value={postText} onChange={e=>setPostText(e.target.value)} placeholder="What has your imagination lately?"/><div className="row between"><small className="muted">{postText.length}/600</small><button className="btn primary" onClick={()=>{if(postText.trim().length<3)return notify("Write at least 3 characters.");setState(s=>({...s,posts:[{id:uid(),userId:user.id,displayName:profile.displayName||user.username,text:postText.trim(),date:new Date().toISOString(),likes:[]},...s.posts]}));setPostText("");notify("Post published.")}}>Publish post</button></div></div><Heading title="Community feed"/>{state.posts.length?state.posts.map(p=><article className="review" key={p.id}><div className="row between"><b>{p.displayName}</b><small className="muted">{new Date(p.date).toLocaleString()}</small></div><p>{p.text}</p><button className="link" onClick={()=>setState(s=>({...s,posts:s.posts.map(x=>x.id===p.id?{...x,likes:(x.likes||[]).includes(user.id)?x.likes.filter(id=>id!==user.id):[...(x.likes||[]),user.id]}:x)}))}>♡ {(p.likes||[]).length} likes</button>{p.userId===user.id&&<button className="link" onClick={()=>setState(s=>({...s,posts:s.posts.filter(x=>x.id!==p.id)}))}> · Delete</button>}</article>):<Empty title="It's quiet in here" body="Start the conversation with your first post."/>}</div><aside><section className="sidebox"><h3>Friend requests</h3>{incoming.length?incoming.map(id=>{const u=state.users.find(x=>x.id===id);return u&&<p key={id} className="row between">{u.username}<button className="btn mini" onClick={()=>setState(s=>({...s,friends:{...s.friends,[user.id]:[...(s.friends[user.id]||[]),id],[id]:[...(s.friends[id]||[]),user.id]},friendRequests:{...s.friendRequests,[user.id]:(s.friendRequests[user.id]||[]).filter(x=>x!==id)}}))}>Accept</button><button className="link" onClick={()=>setState(s=>({...s,friendRequests:{...s.friendRequests,[user.id]:(s.friendRequests[user.id]||[]).filter(x=>x!==id)}}))}>Ignore</button></p>}) : <p className="muted small">No pending requests.</p>}</section><section className="sidebox"><h3>Find people</h3><input value={friendSearch} onChange={e=>setFriendSearch(e.target.value)} placeholder="Search username"/>{others.filter(u=>u.username.toLowerCase().includes(friendSearch.toLowerCase())).map(u=><p className="row between" key={u.id}>@{u.username}<button className="link" onClick={()=>sendFriend(u)}>＋ Add</button></p>)}</section><section className="sidebox"><h3>Your friends</h3>{friends.map(id=>state.users.find(x=>x.id===id)).filter(Boolean).map(u=><p key={u.id}><button className="link" onClick={()=>go(`/profile/${u.username}`)}>{u.displayName||u.username}</button></p>)}</section></aside></div></main>}}

else content=<main className="container page"><Empty title="This page wandered off" body="We couldn't find that page." action="Go home" onAction={()=>go("/")}/></main>;

function Heading({eyebrow,title,action,click}){return <div className="heading">{<div>{eyebrow&&<p className="eyebrow">{eyebrow}</p>}<h2>{title}</h2></div>}{action&&<button className="link" onClick={click}>{action} ↗</button>}</div>}

const privatePath=["/library","/settings","/community","/profile/edit"].includes(path);

useEffect(()=>{if(privatePath&&!user){go("/login")}},[path,user?.id]);

return <div className="app">{Header()}<div className="demo-banner">✦ FictionBook is a local demo · Data stays in this browser <button onClick={()=>setThemeOpen(true)}>Customize theme</button></div>{content}<footer><button className="brand" onClick={()=>go("/")}> <i>f.</i> fiction<span>book</span></button><p>Your worlds, collected.</p><div><button onClick={()=>go("/community")}>Community</button><button onClick={()=>go("/settings")}>Settings</button><button onClick={()=>go("/browse/books")}>Browse books</button></div><small>FictionBook · A personal entertainment library</small></footer>{themeOpen&&<ThemeStudio theme={state.theme} change={t=>setState(s=>({...s,theme:t}))} close={()=>setThemeOpen(false)} toast={notify}/>}{detail&&<TitleDetails t={detail} state={state} user={user} profile={profile} rate={rate} add={add} review={review} close={()=>{setDetail(null);if(path.startsWith("/title/"))go("/")}} allReviews={reviewsFor(detail)} open={t=>{setDetail(t);history.replaceState({},"",`/title/${t.id}`);setPath(`/title/${t.id}`)}} allTitles={allTitles}/>}{toast&&<div className="toast" role="status">{toast}<button onClick={()=>setToast("")}>×</button></div>}{showTour&&user&&<div className="scrim"><section className="tour"><p className="eyebrow">A QUICK TOUR · {tour+1}/3</p><h2>{["Welcome to your worlds.","Build your own library.","Make the space yours."][tour]}</h2><p>{["Discover original fictional titles across seven categories.","Track progress, save a backlog, rate titles and write spoiler-aware reviews.","Choose a custom accent or switch on Rainbow Pride whenever you like."][tour]}</p><div className="row between"><button className="btn ghost" onClick={()=>{setState(s=>({...s,onboardingDone:{...s.onboardingDone,[user.id]:true}}));setShowTour(false)}}>Skip tour</button><button className="btn primary" onClick={()=>{if(tour<2)setTour(t=>t+1);else{setState(s=>({...s,onboardingDone:{...s.onboardingDone,[user.id]:true}}));setShowTour(false);go("/category/watchable")}}}>{tour===2?"Let's explore":"Next →"}</button></div></section></div>}</div>;

}
